const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format(n/100);
let state,stage=0,selected=0,busy=false,previewRun=0;const labels=['Cart','Shipping','Payment'];
const draft=()=>state.draft,item=()=>draft().items[selected],complete=i=>i.designRequested||i.artworkAccepted===true;
function notice(text,error=true){$('#notice').innerHTML=text?`<div class="alert ${error?'error':'success'}">${esc(text)}</div>`:'';}
async function api(path,data){const r=await fetch('/api/checkout/'+path,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,revision:state?.revision??0})});const v=await r.json();if(!r.ok)throw Error(v.error||'Could not save checkout.');return v;}
async function mutate(path,data){state=await api(path,data);selected=Math.min(selected,Math.max(0,draft().items.length-1));return state;}
function tabs(){return draft().items.length>1?`<div class="item-tabs" role="tablist">${draft().items.map((i,n)=>`<button role="tab" aria-selected="${selected===n}" class="${selected===n?'selected':''}" data-item="${n}">${esc(i.jobName||i.name)} ${complete(i)?'✓':''}</button>`).join('')}</div>`:'';}
function itemSpecs(i){return `<div class="specs"><span>Trim size</span><strong>${i.spec.width} × ${i.spec.height} in</strong><span>Bleed per edge</span><strong>${i.spec.bleed} in</strong><span>Printed sides</span><strong>${i.spec.sides}</strong><span>Quantity</span><strong>${esc(i.values.quantity)}</strong>${(i.choices||[]).map(c=>`<span>${esc(c.label)}</span><strong>${esc(c.text)}</strong>`).join('')}</div>`;}
function summary(){const t=state.totals;return `<aside class="summary"><h2>Order summary</h2>${draft().items.map(i=>`<div class="summary-item"><strong>${esc(i.jobName||i.name)}</strong><span>${esc(i.values.quantity)} · ${i.spec.width} × ${i.spec.height} in · ${i.spec.sides} side(s)</span><div>${money(i.price.net)}</div>${i.designRequested?'<small>Includes the product’s design service</small>':''}</div>`).join('')}<div class="summary-total"><span>Subtotal</span><strong>${money(t.subtotal)}</strong></div><div class="summary-total"><span>Shipping</span><strong>${draft().shipping?money(t.shipping):'Select method'}</strong></div><div class="summary-total"><span>Tax${t.taxReady?' · '+t.rate+'%':''}</span><strong>${t.taxReady?money(t.tax):'Choose address'}</strong></div><div class="summary-total grand"><span>${t.taxReady?'Total · CAD':'Before tax · CAD'}</span><strong>${money(t.total??t.subtotal+t.shipping)}</strong></div></aside>`;}

function checks(i){return `${i.artworkError?`<div class="alert error">${esc(i.artworkError)}</div>`:''}${(i.reports||[]).map(r=>`<details open><summary>${esc(r.name)} · ${r.pageCount} page(s)</summary>${r.pages.map(p=>`<p class="muted" style="padding:12px 16px 0">Page ${p.page} · ${p.width.toFixed(3)} × ${p.height.toFixed(3)} in</p>${p.checks.map(c=>`<div class="check-row ${c.status}"><div><strong>${esc(c.name)}</strong><p>${esc(c.detail)}</p></div><span class="status-tag">${c.status==='pass'?'✓ Checked':c.status==='fail'?'× Fix required':'Review required'}</span></div>`).join('')}`).join('')}</details>`).join('')}`;}
function files(i){return i.fileIds.map((id,n)=>{const r=i.reports?.find(r=>r.id===id);return `<div class="file"><div><strong>${esc(r?.name||'Uploaded artwork')}</strong><small>${r?`${(r.size/1024/1024).toFixed(2)} MB · ${r.pageCount} page(s)`:'Needs PDF validation'}</small></div><button class="delete" data-file-remove="${n}">Remove</button></div>`;}).join('');}
function artwork(){const i=item();if(i.designRequested)return `${tabs()}<div class="panel"><h2>${esc(i.name)}</h2><div class="hint">You requested a designer. The design service is included in the estimate. Your designer will prepare artwork for your approval before production.</div><a href="/satin/design-agreement/">Read the Design Policy</a><div class="actions"><button class="btn" data-next>Continue</button></div></div>`;
return `${tabs()}<div class="panel"><div class="panel-heading"><div><h2>Upload your artwork</h2><p class="muted">${esc(i.name)} · ${i.spec.sides} printed side(s)</p></div><a class="btn secondary small" href="/api/checkout/template?item=${i.id}">PDF templates</a></div><label class="upload-zone"><strong>Choose your print PDFs</strong><span class="muted">One multipage PDF or one PDF for each side · maximum 20 MB per file</span><input id="upload" type="file" accept="application/pdf,.pdf" multiple></label>${files(i)}${i.fileIds.length?`<p class="muted" style="margin-top:12px">Expected ${i.spec.sides} page(s) · ${i.reports?.reduce((n,r)=>n+r.pageCount,0)||0} validated page(s) uploaded.</p>`:''}<div class="hint">File validation checks the PDF structure and ordered dimensions. Bleed artwork coverage, effective DPI, CMYK and fonts remain subject to production preflight.</div><div class="checks">${checks(i)}</div><div class="actions"><a class="btn secondary" href="${esc(i.path)}">Edit product options</a><button class="btn" data-next ${validFiles(i)?'':'disabled'}>Review proof</button></div></div><div class="panel"><h3>Prepare your file</h3>${itemSpecs(i)}<ul class="guide-list"><li>Export a print PDF at the ordered trim size with the required bleed.</li><li>Keep text and important details at least 0.125 in inside the trim.</li><li>Use CMYK artwork with embedded or outlined fonts.</li><li>Use 300 DPI images at final print size.</li><li>Remove guides, hidden layers and comments from the print file.</li></ul></div>`;}
function validFiles(i){return !i.artworkError&&i.reports?.length>0&&i.reports.every(r=>r.status!=='rejected')&&i.reports.reduce((n,r)=>n+r.pageCount,0)===i.spec.sides;}
function proof(){const i=item();if(i.designRequested)return artwork();return `${tabs()}<div class="panel"><div class="panel-heading"><div><h2>Review your uploaded files</h2><p class="muted">${esc(i.name)} · check front and back before continuing</p></div>${i.spec.sides===2&&i.fileIds.length===2?'<button class="btn secondary small" data-swap>Swap files</button>':''}</div><div class="proofs" data-previews><p class="muted">Generating preview…</p></div><label class="field" style="margin-top:24px">Item name<input id="job-name" maxlength="120" value="${esc(i.jobName)}" placeholder="e.g. Road Genies business cards"></label><div class="hint">This preview confirms the uploaded file and side order. It does not simulate exact printed colour or overprint. Production preflight is still required.</div><label class="consent"><input type="checkbox" id="approve" ${i.proof?'checked':''}><span>I confirm these are the correct files and printed sides for my order. I understand that the artwork still requires production review.</span></label><div class="actions"><button class="btn secondary" data-back>Back to upload</button><button class="btn" data-proof ${validFiles(i)?'':'disabled'}>Confirm files</button></div></div>`;}
function cart(){return `<div class="panel"><h2>Your shopping cart</h2>${draft().items.map((i,n)=>`<div class="cart-row"><div class="cart-thumb" data-thumbnail="${n}">PDF</div><div><h3>${esc(i.jobName||i.name)}</h3>${itemSpecs(i)}<p class="under-review">${i.designRequested?'Design service requested':i.artworkAccepted?'Artwork accepted · production review pending':'Confirm artwork on the product page'}</p><a class="delete" href="${esc(i.path)}">Edit product / artwork</a><button class="delete" data-remove="${i.id}">Remove item</button></div><span class="item-price">${money(i.price.net)}</span></div>`).join('')}<div class="actions"><a class="btn secondary" href="/satin/print-shop/">Continue shopping</a><button class="btn" data-next ${draft().items.every(complete)?'':'disabled'}>Proceed to shipping</button></div></div>`;}
function shipping(){const a=draft().address||{};return `<form id="address-form" class="panel"><h2>Shipping address</h2><p class="muted">Add the address where this order should be delivered.</p><div class="address-fields">${[['name','Full name','name'],['company','Company (optional)','organization'],['email','Email','email'],['phone','Phone (optional)','tel'],['street1','Street address','address-line1'],['street2','Unit / suite (optional)','address-line2'],['city','City','address-level2']].map(([k,label,auto])=>`<label class="field ${k==='street1'||k==='street2'?'wide':''}">${label}<input name="${k}" autocomplete="${auto}" type="${k==='email'?'email':'text'}" value="${esc(a[k]||'')}" maxlength="${k==='email'?254:160}" ${['company','phone','street2'].includes(k)?'':'required'}></label>`).join('')}<label class="field">Province<select name="state">${['ON','QC','BC','AB','MB','NB','NL','NS','NT','NU','PE','SK','YT'].map(x=>`<option ${x===(a.state||'ON')?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Postal code<input name="zip" autocomplete="postal-code" value="${esc(a.zip||'')}" required maxlength="7" pattern="[A-Za-z][0-9][A-Za-z] ?[0-9][A-Za-z][0-9]" placeholder="L4K 2M4"></label><label class="field">Country<select name="country"><option value="CA">Canada</option></select></label></div><fieldset><legend>Billing address</legend><label><input type="checkbox" name="billingSame" checked> Same as shipping</label><div data-billing-fields hidden>${['name','street1','street2','city','state','zip'].map(k=>`<label class="field">${k}<input name="billing_${k}" maxlength="160" value="${esc(draft().billingAddress?.[k]||'')}"></label>`).join('')}</div></fieldset><div class="actions"><button type="submit" class="btn">Calculate delivery options</button></div></form><div class="panel"><h2>Shipping method</h2>${draft().shippingNotice?`<p class="muted">${esc(draft().shippingNotice)}</p>`:''}${draft().rates.length?`<div class="rate-grid">${draft().rates.map(r=>`<label class="rate"><input type="radio" name="shipping" value="${esc(r.id)}" ${draft().shipping?.id===r.id?'checked':''}><div><strong>${esc(r.label)}</strong><p>${esc(r.detail)}</p><b>${money(Math.round(r.amount*100))}${r.id==='gta-next-day'?' + tax':''}</b></div></label>`).join('')}</div>`:'<p class="muted">Complete your address to see pickup and delivery options.</p>'}<p class="muted">Delivery estimates start when your printed order is ready. GTA flat delivery is $50 before tax for eligible addresses.</p><div class="actions"><button class="btn secondary" data-back>Back to cart</button><button class="btn" data-next ${draft().shipping?'':'disabled'}>Review order</button></div></div>`;}
function payment(){const P=state.payments||{},t=state.totals,a=draft().address||{},ready=t.taxReady,inline=!!P.square&&!sdkFailed.square,pp=!!P.paypal&&!sdkFailed.paypal&&state.connections.paypal,connected=state.connections.square||state.connections.paypal;
return `<div class="panel"><h2>Payment</h2><div class="pay-review"><div><h3>Delivery</h3><p>${esc(a.name)}<br>${esc(a.street1)} ${esc(a.street2)}<br>${esc(a.city)}, ${esc(a.state)} ${esc(a.zip)}</p></div><div><h3>Method</h3><p>${esc(draft().shipping?.label)}<br><span class="muted">${money(Math.round((draft().shipping?.amount||0)*100))} before tax</span></p></div></div>${connected?'':'<div class="hint">Online payment is temporarily unavailable. Your cart and artwork are saved. Please return when checkout is available.</div>'}${!ready?'<div class="hint">Online ordering is not available for this delivery province yet.</div>':''}<label class="consent"><input type="checkbox" id="order-consent"><span>I confirm my order, artwork selection and delivery address. I agree to the <a href="/satin/refund-policy/">Order Policy</a> and <a href="/satin/privacy-policy/">Privacy Policy</a>${draft().items.some(i=>i.designRequested)?' · <a href="/satin/design-agreement/">Design Policy</a>':''}. Artwork requires production preflight before printing.</span></label>
${inline&&ready?`<section class="pay-card" aria-labelledby="pay-card-title"><div class="pay-card-head"><h3 id="pay-card-title">Card details</h3><span class="card-brands" aria-label="Visa, Mastercard, American Express, Discover"><i>VISA</i><i>MC</i><i>AMEX</i><i>DISC</i></span></div><div class="pay-wallets" data-wallets hidden><div id="sq-apple-pay" class="apple-pay-button" role="button" tabindex="0" aria-label="Pay with Apple Pay" hidden></div><div id="sq-google-pay" hidden></div><div class="pay-or"><span>or pay by card</span></div></div><div id="sq-card" class="sq-card"><div class="sq-loading"><span class="spinner"></span>Loading secure card form…</div></div><p class="pay-error" data-card-error role="alert" aria-live="assertive"></p><button class="btn pay-btn" type="button" data-pay-card disabled><span>Pay ${money(t.total||0)}</span></button><p class="secure-note"><svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V8a4 4 0 0 1 8 0v3"/></svg>Secured by Square. Card details are entered in Square’s encrypted form and never reach our servers.</p></section>`:''}
${pp&&ready?`${inline?'<div class="pay-or"><span>or</span></div>':''}<section class="pay-paypal"><div data-paypal-host class="paypal-host"><div class="sq-loading"><span class="spinner"></span>Loading PayPal…</div></div><p class="pay-error" data-paypal-error role="alert" aria-live="assertive"></p></section>`:''}
${!inline||(!pp&&state.connections.paypal)?`<div class="payment-options">${!inline?`<button class="btn" data-pay="square" ${state.connections.square&&ready?'':'disabled'}><strong>Pay ${money(t.total||0)} by credit / debit card</strong><span class="muted">Secure checkout with Square</span></button>`:''}${!pp&&state.connections.paypal?`<button class="btn" data-pay="paypal" ${ready?'':'disabled'}><strong>Pay with PayPal</strong></button>`:''}</div>`:''}<div class="actions"><button class="btn secondary" data-back>Back to shipping</button></div></div>`;}
/* ---------- embedded payments: Square Web Payments SDK + PayPal JS SDK (falls back to redirect checkout) ---------- */
const sdkFailed={square:false,paypal:false},scripts={};let sq=null;
function loadScript(src){if(!scripts[src])scripts[src]=new Promise((resolve,reject)=>{const el=document.createElement('script');el.src=src;el.async=true;const timer=setTimeout(()=>reject(Error('Timed out loading '+src)),15000);el.onload=()=>{clearTimeout(timer);resolve();};el.onerror=()=>{clearTimeout(timer);delete scripts[src];reject(Error('Could not load '+src));};document.head.append(el);});return scripts[src];}
function mountPayments(){const run=previewRun,P=state.payments||{};const fail=k=>e=>{console.warn('payment sdk',k,e);if(run!==previewRun)return;sdkFailed[k]=true;render();};
 if(P.square&&!sdkFailed.square&&$('#sq-card'))mountSquare(run,P.square).catch(fail('square'));
 if(P.paypal&&!sdkFailed.paypal&&$('[data-paypal-host]'))mountPaypal(run,P.paypal).catch(fail('paypal'));}
async function mountSquare(run,P){await loadScript(P.sdk);if(!window.Square)throw Error('Square SDK unavailable');if(!sq||sq.app!==P.applicationId)sq={app:P.applicationId,payments:window.Square.payments(P.applicationId,P.locationId)};
 for(const k of ['card','gp']){try{await sq[k]?.destroy();}catch{}sq[k]=null;}
 const card=await sq.payments.card({style:{input:{fontSize:'16px',color:'#172337'},'input::placeholder':{color:'#8a97ab'},'.input-container':{borderColor:'#dce3ed',borderRadius:'9px'},'.input-container.is-focus':{borderColor:'#172337'},'.input-container.is-error':{borderColor:'#d7004d'}}});
 if(run!==previewRun||!$('#sq-card')){card.destroy();return;}$('#sq-card').innerHTML='';await card.attach('#sq-card');sq.card=card;const b=$('[data-pay-card]');if(b)b.disabled=false;
 try{const total=(state.totals.total/100).toFixed(2),req=sq.payments.paymentRequest({countryCode:'CA',currencyCode:'CAD',total:{amount:total,label:'Satin Graphic'}});let any=false;
  const gp=await sq.payments.googlePay(req).catch(()=>null);if(gp&&run===previewRun&&$('#sq-google-pay')){await gp.attach('#sq-google-pay',{buttonColor:'black',buttonSizeMode:'fill',buttonType:'long'});sq.gp=gp;$('#sq-google-pay').hidden=false;$('#sq-google-pay').onclick=()=>payCard(gp);any=true;}
  const ap=await sq.payments.applePay(req).catch(()=>null);if(ap&&run===previewRun&&$('#sq-apple-pay')){sq.ap=ap;const el=$('#sq-apple-pay');el.hidden=false;el.onclick=()=>payCard(ap);any=true;}
  if(any&&run===previewRun)$('[data-wallets]').hidden=false;}catch{}}
function billingDetails(){const a=draft().billingAddress?.street1?draft().billingAddress:draft().address||{},d=draft().address||{},parts=String(a.name||d.name||'').trim().split(/\s+/);return {amount:(state.totals.total/100).toFixed(2),currencyCode:'CAD',intent:'CHARGE',customerInitiated:true,sellerKeyedIn:false,billingContact:{givenName:parts[0]||'',familyName:parts.slice(1).join(' '),email:d.email||undefined,phone:d.phone||undefined,addressLines:[a.street1,a.street2].filter(Boolean),city:a.city,state:a.state,countryCode:'CA',postalCode:a.zip}};}
async function payCard(wallet){const err=$('[data-card-error]');if(busy||!sq?.card&&!wallet)return;err.textContent='';if(!$('#order-consent')?.checked){err.textContent='Please accept the order terms above before paying.';$('#order-consent').focus();return;}
 const btn=$('[data-pay-card]'),label=btn?.querySelector('span');busy=true;if(btn){btn.disabled=true;btn.classList.add('loading');label.textContent='Processing payment…';}$('#app').setAttribute('aria-busy','true');
 try{const details=billingDetails(),result=wallet?await wallet.tokenize():await sq.card.tokenize(details);
  if(result.status!=='OK')throw Error(result.errors?.[0]?.message||'Check your card details and try again.');
  let verificationToken=null;if(!wallet&&typeof sq.payments.verifyBuyer==='function'){try{verificationToken=(await sq.payments.verifyBuyer(result.token,details))?.token||null;}catch{throw Error('Card verification was not completed. Please try again.');}}
  const data=await api('pay-card',{sourceId:result.token,verificationToken,idempotencyKey:crypto.randomUUID(),consent:true});state.order=data.order;
  if(data.order.status==='paid'){clearPaidCart(data.order);busy=false;render();window.scrollTo({top:0,behavior:'smooth'});return;}
  err.textContent='Your payment is being processed. We will email you as soon as it is confirmed.';
 }catch(e){err.textContent=e.message||'The payment could not be completed. Please try again.';}
 finally{busy=false;$('#app').removeAttribute('aria-busy');const b=$('[data-pay-card]');if(b&&state.order?.status!=='paid'){b.disabled=false;b.classList.remove('loading');b.querySelector('span').textContent='Pay '+money(state.totals.total||0);}}}
async function mountPaypal(run,P){await loadScript('https://www.paypal.com/sdk/js?client-id='+encodeURIComponent(P.clientId)+'&currency=CAD&intent=capture&components=buttons&disable-funding=card,credit,paylater');
 if(!window.paypal?.Buttons)throw Error('PayPal SDK unavailable');const host=$('[data-paypal-host]');if(run!==previewRun||!host)return;let orderId=null;const msg=t=>{const e=$('[data-paypal-error]');if(e)e.textContent=t;};
 const buttons=window.paypal.Buttons({style:{layout:'horizontal',color:'gold',shape:'rect',label:'paypal',height:48,tagline:false},
  onClick:(data,actions)=>{msg('');if(!$('#order-consent')?.checked){msg('Please accept the order terms above before paying.');return actions.reject();}return actions.resolve();},
  createOrder:async()=>{const d=await api('payment',{provider:'paypal',consent:true,popup:true});state.order=d.order;orderId=d.order.id;if(!d.order.paypalOrderId)throw Error('PayPal is unavailable. Try card payment.');return d.order.paypalOrderId;},
  onApprove:async()=>{msg('Confirming your PayPal payment…');try{const d=await api('capture',{id:orderId});state.order=d.order;if(d.order.status==='paid'){clearPaidCart(d.order);render();window.scrollTo({top:0,behavior:'smooth'});return;}msg('PayPal did not confirm the payment. Please try again.');}catch(e){msg(e.message);}},
  onCancel:()=>msg('PayPal payment was cancelled. You can try again.'),onError:e=>msg((e&&e.message)||'PayPal is unavailable. Try card payment.')});
 if(buttons.isEligible&&!buttons.isEligible())throw Error('PayPal not eligible');host.innerHTML='';await buttons.render(host);}

function render(){previewRun++;$('#steps').innerHTML=labels.map((l,n)=>`<li class="${stage===n?'active':''}" ${stage===n?'aria-current="step"':''}><button data-stage="${n}" ${canVisit(n)?'':'disabled'}><span class="step-number">${n+1}</span>${l}</button></li>`).join('');
if(state.order?.status==='paid'){const o=state.order;$('#app').innerHTML=`<div class="panel empty"><p class="eyebrow">PAYMENT CONFIRMED</p><h2>${esc(o.reference)}</h2><p>${money(o.snapshot.totals.total)} CAD · ${o.card?esc(o.card):o.provider==='paypal'?'PayPal':esc(o.provider)}</p><p>Your order is placed. We will check the artwork before production.</p>${o.snapshot.items.filter(i=>i.digitalKey).map(i=>`<p><a class="btn" href="/api/digital/download?order=${o.id}&item=${i.id}">Download ${esc(i.name)}</a></p>`).join('')}<a class="btn" href="/satin/print-shop/">Continue shopping</a><button class="btn secondary" data-new>Start another order</button></div>`;return;}if(draft().submitted){try{const keys=new Set(draft().items.map(i=>String(i.sourceKey)));localStorage.setItem('sg-cart',JSON.stringify(JSON.parse(localStorage.getItem('sg-cart')||'[]').filter(a=>!keys.has(String(a.id)))));}catch{}$('#app').innerHTML=`<div class="panel empty"><p class="eyebrow">ORDER RECEIVED</p><h2>${esc(draft().submitted.reference)}</h2><p>Thank you — your order is in. We will check your artwork and email you a secure payment link to complete payment. No payment has been taken yet.</p><a class="btn" href="/satin/print-shop/">Return to the print shop</a><button class="btn secondary" style="margin-left:12px" data-new>Start another checkout</button></div>`;return;}
if(!draft().items.length){$('#app').innerHTML='<div class="panel empty"><h2>Your cart is empty</h2><p>Configure a print product and upload your artwork, then add it to your cart. Vehicle wraps and other custom services continue through the quote request.</p><a class="btn" href="/satin/shop/">Browse products</a></div>';return;}
$('#app').innerHTML=`<div class="layout"><div>${[cart,shipping,payment][stage]()}</div>${summary()}</div>`;if(stage===0)for(const [n,i] of draft().items.entries())thumbnail(i,n);if(stage===2)mountPayments();}
function canVisit(n){return n===0||n===1&&draft().items.every(complete)||n===2&&draft().address&&draft().shipping&&draft().items.every(complete);}
async function pdf(){const lib=await import('/checkout/vendor/pdf.mjs');lib.GlobalWorkerOptions.workerSrc='/checkout/vendor/pdf.worker.mjs';return lib;}
async function previews(i){const run=previewRun,host=$('[data-previews]');try{const lib=await pdf();const canvases=[];for(const id of i.fileIds){const response=await fetch('/api/studio/file?id='+encodeURIComponent(id));if(!response.ok)throw Error('Artwork is unavailable. Re-upload it.');const doc=await lib.getDocument({data:new Uint8Array(await response.arrayBuffer()),isEvalSupported:false}).promise;try{for(let n=1;n<=doc.numPages;n++){const page=await doc.getPage(n),scale=720/page.getViewport({scale:1}).width,viewport=page.getViewport({scale}),canvas=document.createElement('canvas');canvas.width=viewport.width;canvas.height=viewport.height;await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;canvases.push(canvas);}}finally{await doc.destroy();}}
 if(run!==previewRun||!host?.isConnected)return;host.replaceChildren();for(const [n,c] of canvases.entries()){const frame=document.createElement('div');frame.className='proof-frame';const label=document.createElement('p');label.className='caption';label.textContent=n===0?'Front / page 1':'Back / page 2';frame.append(label,c);host.append(frame);}
}catch(e){if(run===previewRun&&host?.isConnected)host.innerHTML=`<p class="alert error">Preview unavailable: ${esc(e.message)}. Download and review the original file before confirming.</p>${i.fileIds.map(id=>`<a href="/api/studio/file?id=${id}">Download original PDF</a>`).join(' ')}`;}}
async function thumbnail(i,n){const host=$(`[data-thumbnail="${n}"]`),run=previewRun;if(!i.fileIds.length)return;try{const lib=await pdf(),r=await fetch('/api/studio/file?id='+i.fileIds[0]);if(!r.ok)return;const doc=await lib.getDocument({data:new Uint8Array(await r.arrayBuffer()),isEvalSupported:false}).promise;try{const page=await doc.getPage(1),viewport=page.getViewport({scale:160/page.getViewport({scale:1}).width}),canvas=document.createElement('canvas');canvas.width=viewport.width;canvas.height=viewport.height;await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;if(run===previewRun&&host?.isConnected)host.replaceChildren(canvas);}finally{await doc.destroy();}}catch{}}
async function perform(fn){if(busy)return;busy=true;notice('');$('#app').setAttribute('aria-busy','true');document.querySelectorAll('#app button').forEach(b=>b.disabled=true);try{await fn();}catch(e){notice(e.message);}finally{busy=false;render();$('#app').removeAttribute('aria-busy');}}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.hasAttribute('data-pay-card')){payCard();return;}
if(t.id==='account'){ $('#account-dialog').showModal();return;}if(t.classList.contains('dialog-close')){$('#account-dialog').close();return;}
if(t.dataset.stage!==undefined){const n=Number(t.dataset.stage);if(canVisit(n)){stage=n;render();}return;}
if(t.dataset.item!==undefined){selected=Number(t.dataset.item);render();return;}
if(t.dataset.review!==undefined){selected=Number(t.dataset.review);stage=0;render();return;}
if(t.hasAttribute('data-back')){stage=Math.max(0,stage-1);render();return;}
if(t.hasAttribute('data-next')){stage=Math.min(2,stage+1);render();window.scrollTo({top:0,behavior:'smooth'});return;}
if(t.dataset.fileRemove!==undefined)perform(async()=>{await mutate('item',{id:item().id,fileIds:item().fileIds.filter((_,n)=>n!==Number(t.dataset.fileRemove))});});
if(t.hasAttribute('data-swap'))perform(async()=>{await mutate('item',{id:item().id,fileIds:[...item().fileIds].reverse()});});
if(t.hasAttribute('data-proof'))perform(async()=>{if(!$('#approve')?.checked)throw Error('Confirm that the files and side order are correct.');await mutate('item',{id:item().id,proof:true,jobName:$('#job-name').value});if(draft().items.every(complete))stage=2;else{selected=draft().items.findIndex(i=>!complete(i));stage=0;}});
if(t.dataset.remove)perform(async()=>{const i=draft().items.find(i=>i.id===t.dataset.remove);await mutate('item',{id:i.id,remove:true});try{const original=JSON.parse(localStorage.getItem('sg-cart')||'[]');localStorage.setItem('sg-cart',JSON.stringify(original.filter(a=>String(a.id)!==i.sourceKey)));}catch{}});
if(t.dataset.pay)perform(async()=>{if(!$('#order-consent')?.checked)throw Error('Read and accept the order terms before payment.');const data=await api('payment',{provider:t.dataset.pay,consent:true});state.order=data.order;if(data.order.status==='paid'){clearPaidCart(data.order);return;}location.assign(data.order.url);});

if(t.hasAttribute('data-new'))perform(async()=>{await mutate('new',{});stage=0;history.replaceState(null,'','/satin/checkout/');});
});
document.addEventListener('submit',e=>{if(e.target.id!=='address-form')return;e.preventDefault();const a=Object.fromEntries(new FormData(e.target));perform(async()=>{const billing=a.billingSame==='on'?a:{...Object.fromEntries(['name','street1','street2','city','state','zip'].map(k=>[k,a['billing_'+k]])),email:a.email,country:'CA'};await mutate('shipping',{address:a,billingAddress:billing});});});
document.addEventListener('change',e=>{if(e.target.name==='billingSame'){document.querySelector('[data-billing-fields]').hidden=e.target.checked;document.querySelectorAll('[data-billing-fields] input').forEach(i=>i.required=!e.target.checked&&!['billing_street2'].includes(i.name));}if(e.target.name==='shipping'){const id=e.target.value;perform(async()=>{await mutate('select-shipping',{id});});}if(e.target.id==='upload'){const chosen=[...e.target.files];perform(async()=>{if(!chosen.length)return;const i=item(),newIds=[];if(i.fileIds.length+chosen.length>i.spec.sides)throw Error('Remove an existing file before uploading a replacement.');for(const file of chosen){if(file.size>20000000)throw Error('Each PDF must be smaller than 20 MB.');if(!/\.pdf$/i.test(file.name))throw Error('Upload print-ready PDF files.');const fd=new FormData();fd.set('file',file);const r=await fetch('/api/studio/upload',{method:'POST',body:fd}),v=await r.json();if(!r.ok)throw Error(v.error);newIds.push(v.file.id);}const combined=[...i.fileIds,...newIds];if(combined.length>i.spec.sides)throw Error(`Remove an existing file before uploading more than ${i.spec.sides} files.`);await mutate('item',{id:i.id,fileIds:combined});});}});
function clearPaidCart(order){const keys=new Set(order.snapshot.items.map(i=>i.sourceKey));try{localStorage.setItem('sg-cart',JSON.stringify(JSON.parse(localStorage.getItem('sg-cart')||'[]').filter(a=>!keys.has(String(a.id)))));}catch{}}
async function start(){try{const session=await fetch('/api/studio/session',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!session.ok)throw Error('Could not start your artwork session. Please retry.');state=await api('draft');if(draft().submitted?.status==='paid'){state.order=(await api('order?id='+encodeURIComponent(draft().submitted.orderId))).order;clearPaidCart(state.order);render();return;}const paymentId=new URLSearchParams(location.search).get('payment');if(paymentId){const data=await api('order?id='+encodeURIComponent(paymentId));state.order=data.order;if(data.order.provider==='paypal'&&data.order.status!=='paid'&&!new URLSearchParams(location.search).has('cancelled')){state.order=(await api('capture',{id:paymentId})).order;}if(state.order.status==='paid'){clearPaidCart(state.order);render();return;}stage=2;notice('Payment is not confirmed. Your cart and artwork are saved. You can retry payment.',false);render();return;}if(!draft().submitted){let local=[];try{local=JSON.parse(localStorage.getItem('sg-cart')||'[]');}catch{}if(local.length)state=await api('import',{items:local.slice(0,30)});}render();}catch(e){notice(e.message);$('#app').innerHTML='<div class="panel empty"><h2>Checkout is temporarily unavailable</h2><p>Your original cart and artwork are unchanged. Please retry.</p><button class="btn" onclick="location.reload()">Retry</button><a class="btn secondary" href="/satin/">Back to Satin</a></div>';}}
start();
